  const isMenuLocked = useCallback((key: MenuLockKey) => Boolean(menuLocks[key]), [menuLocks]);
  const bgmAutoLockedMenusRef = useRef<{ style: boolean; sound: boolean }>({ style: false, sound: false });


  const [selectedStyles, setSelectedStyles] = useState<string[]>([]);
  const [selectedInstrumentSounds, setSelectedInstrumentSounds] = useState<string[]>([]);
  const [selectedPointSounds, setSelectedPointSounds] = useState<string[]>([]);
  const [isPointSoundMode, setIsPointSoundMode] = useState(false);
  const hasSelectedInstrumentalBgm = useMemo(
    () => hasInstrumentalBgmGenreIds([...selectedGenres, ...subGenre]),
    [selectedGenres, subGenre]
  );

  useEffect(() => {
    if (hasSelectedInstrumentalBgm) {
      setSelectedStyles((prev) => (prev.length ? [] : prev));
      setSelectedInstrumentSounds((prev) => (prev.length ? [] : prev));
      setSelectedPointSounds((prev) => (prev.length ? [] : prev));
      setIsPointSoundMode(false);
      setMenuLocks((prev) => {
        const auto = { ...bgmAutoLockedMenusRef.current };
        const next = { ...prev };
        if (!prev.style) {
          next.style = true;
          auto.style = true;
        }
        if (!prev.sound) {
          next.sound = true;
          auto.sound = true;
        }
        bgmAutoLockedMenusRef.current = auto;
        return next;
      });
      return;
    }

    setMenuLocks((prev) => {
      const auto = bgmAutoLockedMenusRef.current;
      if (!auto.style && !auto.sound) return prev;
      const next = { ...prev };
      if (auto.style) next.style = false;
      if (auto.sound) next.sound = false;
      bgmAutoLockedMenusRef.current = { style: false, sound: false };
      return next;
    });
  }, [hasSelectedInstrumentalBgm]);
  
  const [lyricsLength, setLyricsLength] = useState<LyricsLength>('normal');
  const [songStructure, setSongStructure] = useState<SongStructure>('1');
  const [sectionVocalCueEnabled, setSectionVocalCueEnabled] = useState(true);
  const [sectionInstrumentCueEnabled, setSectionInstrumentCueEnabled] = useState(true);
  const [vocalMode, setVocalMode] = useState<VocalMode>('solo');
  const [vocalTones, setVocalTones] = useState<VocalTone[]>(VOCAL_TONES);
  const [selectedVocalToneId, setSelectedVocalToneId] = useState<string | undefined>(undefined);
  const [maleCount, setMaleCount] = useState(0);
  const [femaleCount, setFemaleCount] = useState(0);
  const [vocalMembers, setVocalMembers] = useState<VocalMember[]>([
    { id: 'member_default_solo', gender: 'neutral', roles: ['main'] },
  ]);
  const [vocalRandomActivationKey, setVocalRandomActivationKey] = useState(0);
  const [rapEnabled, setRapEnabled] = useState(false);
  const [rapMode, setRapMode] = useState<RapMode>(() => readStoredRapMode());
  const [lyricWritingStyle, setLyricWritingStyle] = useState<V1LyricWritingStyle>(() => readStoredV1LyricWritingStyle());
  useEffect(() => {
    // Rap Mode is an explicit global studio preference. Vocal-role edits must not
    // silently switch OFF/AUTO/ON behind the user's back.
    setRapEnabled(rapMode === 'on');
    writeStoredRapMode(rapMode);
  }, [rapMode]);
  useEffect(() => {
    const minimumCount = vocalMode === 'group' ? 2 : 1;
    const currentM = vocalMembers.filter((member) => member.gender === 'male').length;
    const currentF = vocalMembers.filter((member) => member.gender === 'female').length;
    const hasMinimumCards = vocalMembers.length >= minimumCount;

    if (currentM === maleCount && currentF === femaleCount && hasMinimumCards) return;

    setVocalMembers((previous) => {
      const next = previous.slice(0, vocalMode === 'solo' ? 1 : MAX_GROUP_VOCAL_MEMBERS).map((member) => ({ ...member }));
      const targetMinimum = vocalMode === 'group' ? 2 : 1;

      while (next.length < targetMinimum) {
        const index = next.length;
        next.push({
          id: `member_default_${vocalMode}_${index}_${Date.now()}`,
          gender: 'neutral',
          roles: index === 0 ? ['main'] : index === 1 ? ['lead'] : ['sub'],
        });
      }

      let maleRemaining = Math.max(0, maleCount);
      let femaleRemaining = Math.max(0, femaleCount);

      // Preserve already assigned genders only while the matching external count still requests them.
      for (let index = 0; index < next.length; index += 1) {
        const member = next[index];
        if (member.gender === 'male' && maleRemaining > 0) {
          maleRemaining -= 1;
          continue;
        }
        if (member.gender === 'female' && femaleRemaining > 0) {
          femaleRemaining -= 1;
          continue;
        }
        next[index] = { ...member, gender: 'neutral' };
      }

      const assignGender = (gender: 'male' | 'female') => {
        const neutralIndex = next.findIndex((member) => member.gender === 'neutral');
        if (neutralIndex >= 0) {
          next[neutralIndex] = { ...next[neutralIndex], gender };
          return;
        }
        if (next.length >= MAX_GROUP_VOCAL_MEMBERS || vocalMode === 'solo') return;
        const index = next.length;
        next.push({
          id: `member_${Date.now()}_${index}`,
          gender,
          roles: index === 0 ? ['main'] : index === 1 ? ['lead'] : ['sub'],
        });
      };

      while (maleRemaining > 0) {
        assignGender('male');
        maleRemaining -= 1;
      }
      while (femaleRemaining > 0) {
        assignGender('female');
        femaleRemaining -= 1;
      }

      return next;
    });
  }, [maleCount, femaleCount, vocalMode]);

