const isVocalCharacterScaleDefaultLevel = (config: VocalCharacterScaleConfig, level: number) => {
  return level === config.defaultValue;
};

const isVocalCharacterOrnamentConfig = (config: VocalCharacterScaleConfig) => config.key === 'ornamentLevel';

const getVocalCharacterOrnamentSecondaryLevel = (character: VocalMember['character'] | undefined, config: VocalCharacterScaleConfig) => {
  const value = Number((character as any)?.ornamentSecondaryLevel);
  return Number.isFinite(value) ? Math.min(config.steps.length, Math.max(1, Math.round(value))) : config.defaultValue;
};

const getVocalCharacterScaleStep = (key: VocalCharacterScaleKey, level?: number) => {
  const config = VOCAL_CHARACTER_SCALE_CONFIGS.find((item) => item.key === key);
  if (!config) return undefined;
  const safeLevel = Math.min(config.steps.length, Math.max(1, Number(level || config.defaultValue)));
  return config.steps[safeLevel - 1];
};

const getVocalCharacterScaleLevel = (character: VocalMember['character'] | undefined, config: VocalCharacterScaleConfig) => {
  const value = Number(character?.[config.key]);
  return Number.isFinite(value) ? Math.min(config.steps.length, Math.max(1, Math.round(value))) : config.defaultValue;
};

const getVocalCharacterScalePromptParts = (character?: VocalMember['character']) => {
  if (!character) return [] as string[];
  const parts = VOCAL_CHARACTER_SCALE_CONFIGS
    .map((config) => {
      const value = Number(character[config.key]);
      if (!Number.isFinite(value)) return '';
      const safeLevel = Math.min(config.steps.length, Math.max(1, Math.round(value)));
      if (isVocalCharacterScaleDefaultLevel(config, safeLevel)) return '';
      return config.steps[safeLevel - 1]?.prompt || '';
    })
    .filter(Boolean);

  const ornamentConfig = VOCAL_CHARACTER_SCALE_CONFIGS.find((config) => isVocalCharacterOrnamentConfig(config));
  if (ornamentConfig) {
    const mainValue = Number(character.ornamentLevel);
    const mainSafeValue = Number.isFinite(mainValue) ? Math.min(ornamentConfig.steps.length, Math.max(1, Math.round(mainValue))) : ornamentConfig.defaultValue;
    const secondaryValue = Number((character as any).ornamentSecondaryLevel);
    const secondarySafeValue = Number.isFinite(secondaryValue) ? Math.min(ornamentConfig.steps.length, Math.max(1, Math.round(secondaryValue))) : ornamentConfig.defaultValue;

    if (Number.isFinite(secondaryValue) && !isVocalCharacterScaleDefaultLevel(ornamentConfig, secondarySafeValue)) {
      const prompt = ornamentConfig.steps[secondarySafeValue - 1]?.prompt;
      if (prompt) parts.push(prompt);
    }
  }

  return parts;
};



const pickOne = <T,>(items: readonly T[], fallback: T): T => {
  if (!items.length) return fallback;
  return items[Math.floor(Math.random() * items.length)] ?? fallback;
};

const getRandomLevel = (levels: number[]) => pickOne(levels, 6);

const hasGenreSignal = (genreHints: string[] | undefined, signals: string[]) => {
  const text = (genreHints || []).join(' ').toLowerCase();
  return signals.some((signal) => text.includes(signal));
};

const isRapLikeGenre = (genreHints?: string[]) => hasGenreSignal(genreHints, ['rap', 'hip', 'drill', 'trap', 'boom', 'garage', 'grime']);
const isRockLikeGenre = (genreHints?: string[]) => hasGenreSignal(genreHints, ['rock', 'punk', 'metal', 'band', 'emo']);
const isRnbLikeGenre = (genreHints?: string[]) => hasGenreSignal(genreHints, ['rnb', 'r&b', 'soul', 'neo_soul', 'neo soul']);
const isDreamyLikeGenre = (genreHints?: string[]) => hasGenreSignal(genreHints, ['dream', 'lofi', 'lo-fi', 'ambient', 'shoegaze', 'city', 'chill', 'jazz']);
const isTrotLikeGenre = (genreHints?: string[]) => hasGenreSignal(genreHints, ['trot', 'enka']);
const isDanceLikeGenre = (genreHints?: string[]) => hasGenreSignal(genreHints, ['edm', 'house', 'dance', 'disco', 'funk', 'kpop', 'k-pop', 'jpop', 'j-pop']);

const buildRandomVocalCharacter = (
  gender: VocalMember['gender'],
  index: number,
  total: number,
  genreHints?: string[],
): VocalCharacterSelection => {
  const isRap = isRapLikeGenre(genreHints);
  const isRock = isRockLikeGenre(genreHints);
  const isRnb = isRnbLikeGenre(genreHints);
  const isDreamy = isDreamyLikeGenre(genreHints);
  const isTrot = isTrotLikeGenre(genreHints);
  const isDance = isDanceLikeGenre(genreHints);

  const voiceTonePools: string[][] = [
    gender === 'male' ? ['heavy', 'husky_tone', 'dry'] : gender === 'female' ? ['clear', 'bright', 'wet'] : ['calm', 'clear', 'airy'],
    gender === 'male' ? ['calm', 'dry', 'lazy'] : gender === 'female' ? ['airy', 'first_love', 'clear'] : ['dry', 'relaxed', 'clear'],
    gender === 'male' ? ['wet', 'bright', 'heavy'] : gender === 'female' ? ['hollow', 'lazy', 'wet'] : ['wet', 'bright', 'hollow'],
  ];
  if (isRap || isRock) voiceTonePools.unshift(gender === 'male' ? ['dry', 'husky_tone', 'heavy'] : gender === 'female' ? ['bright', 'dry', 'husky_tone'] : ['dry', 'bright', 'husky_tone']);
  if (isRnb) voiceTonePools.unshift(['wet', 'lazy', 'clear']);
  if (isDreamy) voiceTonePools.unshift(['airy', 'hollow', 'lazy']);
  if (isDance) voiceTonePools.unshift(['bright', 'clear', 'wet']);
  if (isTrot) voiceTonePools.unshift(gender === 'male' ? ['heavy', 'wet', 'husky_tone'] : gender === 'female' ? ['wet', 'clear', 'bright'] : ['wet', 'clear', 'calm']);

  const personalityPools: string[][] = [
    ['relaxed', 'cool', 'plain'],
    ['sensitive', 'unable_to_let_go', 'frustrated'],
    ['bouncy', 'sly', 'proud'],
  ];
  if (isRap) personalityPools.unshift(['cool', 'proud', 'sly']);
  if (isRock) personalityPools.unshift(['stubborn', 'frustrated', 'proud']);
  if (isRnb || isDreamy) personalityPools.unshift(['relaxed', 'sensitive', 'unable_to_let_go']);
  if (isDance) personalityPools.unshift(['bouncy', 'cute', 'sly']);

  const techniquePools: string[][] = [
    ['breathy', 'vibrato', 'glissando'],
    ['muted_pronunciation', 'ghost_note', 'half_air_stop'],
    ['mixed_voice', 'layback', 'blue_note'],
    ['vocal_fry', 'creaky_voice', 'slurring'],
  ];
  if (isRap) techniquePools.unshift(['anticipation', 'sprechgesang', 'muted_pronunciation']);
  if (isRock) techniquePools.unshift(['edge_voice', 'belting', 'growling']);
  if (isRnb) techniquePools.unshift(['mixed_voice', 'glissando', 'blue_note']);
  if (isDreamy) techniquePools.unshift(['airy', 'ghost_note', 'off_mic']);
  if (isTrot) techniquePools.unshift(['vibrato', 'bending', 'chest_voice']);
  if (isDance) techniquePools.unshift(['anticipation', 'mixed_voice', 'staccato_breath']);

  const tonePool = voiceTonePools[index % voiceTonePools.length] || voiceTonePools[0] || ['calm'];
  const personalityPool = personalityPools[index % personalityPools.length] || personalityPools[0] || ['plain'];
  const techniquePool = techniquePools[index % techniquePools.length] || techniquePools[0] || ['breathy'];
  const techniqueCount = total >= 3 ? 2 : 1;
  const techniqueStart = Math.floor(Math.random() * techniquePool.length);
  const techniqueIds = Array.from({ length: techniqueCount }, (_, offset) => techniquePool[(techniqueStart + offset) % techniquePool.length]).filter(Boolean);

  return {
    voiceToneId: pickOne(tonePool, 'calm'),
    personalityId: pickOne(personalityPool, 'plain'),
    techniqueIds: Array.from(new Set(techniqueIds)),
    ageLevel: getRandomLevel(index % 2 === 0 ? [4, 5, 6, 7] : [5, 6, 7, 8]),
    rangeLevel: gender === 'male'
      ? getRandomLevel(index % 2 === 0 ? [3, 4, 5, 6] : [4, 5, 6, 7])
      : gender === 'female'
        ? getRandomLevel(index % 2 === 0 ? [6, 7, 8, 9] : [5, 6, 7, 8])
        : getRandomLevel([4, 5, 6, 7, 8]),
    deliveryLevel: isRap
      ? getRandomLevel([9, 10, 11])
      : isRock
        ? getRandomLevel([7, 8, 9])
        : isDreamy
          ? getRandomLevel([1, 2, 3, 4, 5])
          : getRandomLevel([4, 5, 6, 7, 8]),
    rhythmLevel: isRap || isDance
      ? getRandomLevel([2, 3, 4, 7])
      : isDreamy
        ? getRandomLevel([6, 7, 8, 10])
        : getRandomLevel([4, 5, 6, 7]),
    emotionLevel: isRock || isTrot
      ? getRandomLevel([7, 8, 9])
      : isDreamy
        ? getRandomLevel([3, 4, 5, 6])
        : getRandomLevel([5, 6, 7, 8]),
    textureLevel: isDreamy
      ? getRandomLevel([8, 9, 10, 11])
      : isRap || isRock
        ? getRandomLevel([2, 3, 4, 5])
        : getRandomLevel([5, 6, 7, 8, 9]),
    charmLevel: isDance
      ? getRandomLevel([3, 4, 7, 8])
      : isRnb
        ? getRandomLevel([7, 8, 11])
        : getRandomLevel([4, 5, 6, 7, 8, 9]),
    ornamentLevel: isRap
      ? getRandomLevel([2, 3, 4, 9, 10])
      : isRock
        ? getRandomLevel([7, 10, 12, 13])
        : isDreamy
          ? getRandomLevel([5, 6, 9, 11])
          : getRandomLevel([3, 5, 6, 8, 9, 11, 13]),
    ornamentSecondaryLevel: total >= 2
      ? getRandomLevel(index % 2 === 0 ? [4, 5, 6, 9, 10] : [2, 7, 11, 12, 13])
      : undefined,
  };
};

const buildAutoVocalRoles = (index: number, total: number, genreHints?: string[]): VocalRole[] => {
  const rapLike = isRapLikeGenre(genreHints);
  if (total <= 1) return rapLike ? ['main', 'rapper'] : ['main'];
  if (rapLike) {
    if (index === 0) return ['main'];
    if (index === 1) return ['rapper'];
    return ['lead'];
  }
  if (index === 0) return ['main'];
  if (index === 1) return ['lead'];
  return ['sub'];
};

const createRandomVocalMember = (
  gender: VocalMember['gender'],
  index: number,
  total: number,
  genreHints?: string[],
): VocalMember => ({
  id: `member_${Date.now()}_${Math.random().toString(36).slice(2, 8)}_${index}`,
  gender,
  roles: buildAutoVocalRoles(index, total, genreHints),
  character: buildRandomVocalCharacter(gender, index, total, genreHints),
});

const pickRecommendedSoloVocalGender = (genreHints?: string[]): 'male' | 'female' => {
  const text = (genreHints || []).join(' ').toLowerCase();
  let maleWeight = 1;
  let femaleWeight = 1;

  // 장르/질감 힌트에 따라 살짝 가중치만 준다. 확정값이 아니라 무작위 추천이다.
  if (/rap|hip|drill|trap|boom|grime|rock|punk|metal|band|trot|enka/.test(text)) maleWeight += 1.1;
  if (/rnb|r&b|soul|neo[_ -]?soul|dream|lofi|lo-fi|ambient|shoegaze|city|jazz|kpop|k-pop|jpop|j-pop|dance|house|disco|funk|cute|bright/.test(text)) femaleWeight += 1.1;
  if (/ballad|folk|acoustic|indie|pop/.test(text)) {
    maleWeight += 0.4;
    femaleWeight += 0.4;
  }

  return Math.random() * (maleWeight + femaleWeight) < maleWeight ? 'male' : 'female';
};

const buildRandomVocalGenderSequence = (count: number): Array<'male' | 'female'> => {
  const safeCount = Math.min(3, Math.max(2, Math.round(count)));
  const templates: Array<Array<'male' | 'female'>> = safeCount === 3
    ? [
        ['male', 'male', 'male'],
        ['female', 'female', 'female'],
        ['male', 'male', 'female'],
        ['male', 'female', 'male'],
        ['female', 'male', 'male'],
        ['female', 'female', 'male'],
        ['female', 'male', 'female'],
        ['male', 'female', 'female'],
      ]
    : [
        ['male', 'male'],
        ['female', 'female'],
        ['male', 'female'],
        ['female', 'male'],
      ];
  return pickOne(templates, templates[0] || ['male', 'female']);
};

const createRandomVocalGroupMembers = (
  genreHints?: string[],
  preferredCount?: number,
): VocalMember[] => {
  const count = preferredCount || (2 + Math.floor(Math.random() * 2));
  const genders = buildRandomVocalGenderSequence(count);
  return genders.map((gender, index) => createRandomVocalMember(gender, index, genders.length, genreHints));
};

const isDefaultAutoGroupMembers = (members: VocalMember[], maleCount: number, femaleCount: number) => {
  if (maleCount !== 1 || femaleCount !== 1 || members.length !== 2) return false;
  const [first, second] = members;
  if (!first || !second) return false;
  const firstDefault = first.gender === 'neutral' && isArrayEqual(first.roles || [], ['main']) && !first.character && !first.toneId;
  const secondDefault = second.gender === 'neutral' && isArrayEqual(second.roles || [], ['lead']) && !second.character && !second.toneId;
  return firstDefault && secondDefault;
};

interface VocalControlProps {
  maleCount: number;
  femaleCount: number;
  vocalMode: VocalMode;
  vocalTones: VocalTone[];
  vocalMembers: VocalMember[];
  rapEnabled: boolean;
  rapMode: RapMode;
  onRapModeChange: (mode: RapMode) => void;
  onMaleChange: (count: number) => void;
  onFemaleChange: (count: number) => void;
  onModeChange: (mode: VocalMode) => void;
  onMembersChange: (members: VocalMember[]) => void;
  onRapChange: (enabled: boolean) => void;
  isKoreanEnglishMix: boolean;
  englishMixRatio: number;
  onEnglishMixRatioChange: (ratio: number) => void;
  onToggleKoreanEnglishMix: () => void;
  onClear: () => void;
  isLocked?: boolean;
  onToggleLock?: () => void;
  onHover: (item: CategoryItem | null) => void;
  onLongPressStart: (item: CategoryItem) => void;
  onLongPressEnd: () => void;
  onModalStateChange?: (isOpen: boolean) => void;
  genreHints?: string[];
  randomActivationKey?: number;
}

function VocalControlComponent({ 
  maleCount, 
  femaleCount, 
  vocalMode,
  vocalTones,
  vocalMembers,
  rapEnabled,
  rapMode,
  onRapModeChange,
  isKoreanEnglishMix,
  englishMixRatio,
  onEnglishMixRatioChange,
  onToggleKoreanEnglishMix,
  onMaleChange, 
  onFemaleChange, 
  onModeChange,
  onMembersChange,
  onRapChange,
  onClear,
  isLocked = false,
  onToggleLock,
  onHover, 
  onLongPressStart, 
  onLongPressEnd,
  onModalStateChange,
  genreHints = [],
  randomActivationKey = 0,
}: VocalControlProps) {
  const [showTitleTooltip, setShowTitleTooltip] = useState(false);
  const [editingVocalMemberId, setEditingVocalMemberId] = useState<string | null>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Height is now handled by overflow-visible
  }, [maleCount, femaleCount, vocalMode, vocalMembers, rapEnabled, isKoreanEnglishMix]);
  const [activeVocalTonePopup, setActiveVocalTonePopup] = useState<string | null>(null);
  const [memberToneDirectInputId, setMemberToneDirectInputId] = useState<string | null>(null);
  const [memberToneDirectDraft, setMemberToneDirectDraft] = useState('');
  const [vocalTonePopupPos, setVocalTonePopupPos] = useState({ top: 0, left: 0, width: 560, maxHeight: 320 });
  const [isVocalRandomActive, setIsVocalRandomActive] = useState(false);
  const [vocalCompositionSource, setVocalCompositionSource] = useState<'empty' | 'manual' | 'random'>('empty');
  const lastRandomActivationKeyRef = useRef(randomActivationKey);

  useEffect(() => {
    if (!randomActivationKey || lastRandomActivationKeyRef.current === randomActivationKey) return;
    lastRandomActivationKeyRef.current = randomActivationKey;
    setIsVocalRandomActive(true);
    setVocalCompositionSource('random');
  }, [randomActivationKey]);

  const updateMemberTonePopupPos = useCallback((trigger?: HTMLElement | null) => {
    const target = trigger || document.querySelector(`[data-tone-trigger="${activeVocalTonePopup || ''}"]`) as HTMLElement | null;
    const rect = target?.getBoundingClientRect();
    if (!rect) return;

    // 멤버 카드/스크롤 부모 아래에 묶이지 않도록 Portal + fixed 좌표로 최상단 레이어에서 띄운다.
    // 버튼이 역할 버튼 라인으로 이동했기 때문에, 버튼 폭이 아니라 드롭다운에 필요한 최소 폭을 보장한다.
    const viewportPadding = 12;
    const width = Math.max(280, Math.min(340, window.innerWidth - viewportPadding * 2));
    const left = Math.min(
      Math.max(rect.right - width, viewportPadding),
      window.innerWidth - width - viewportPadding
    );
    const bottomSpace = window.innerHeight - rect.bottom - viewportPadding;
    const topSpace = rect.top - viewportPadding;
    const shouldOpenAbove = bottomSpace < 190 && topSpace > bottomSpace;
    const maxHeight = Math.max(170, Math.min(320, shouldOpenAbove ? topSpace - 6 : bottomSpace));
    const top = shouldOpenAbove ? Math.max(viewportPadding, rect.top - maxHeight - 6) : rect.bottom + 6;

    setVocalTonePopupPos({ top, left, width, maxHeight });
  }, [activeVocalTonePopup]);

  const handleVocalToneClick = (e: React.MouseEvent, id: string) => {
    const trigger = e.currentTarget as HTMLElement;
    if (activeVocalTonePopup === id) {
      setActiveVocalTonePopup(null);
      setMemberToneDirectInputId(null);
      setMemberToneDirectDraft('');
      return;
    }
    setMemberToneDirectInputId(null);
    setMemberToneDirectDraft('');
    updateMemberTonePopupPos(trigger);
    setActiveVocalTonePopup(id);
  };

  const startMemberToneDirectInput = (member: VocalMember) => {
    setMemberToneDirectInputId(member.id);
    setMemberToneDirectDraft(getVocalToneDisplayLabel(member.toneId, vocalTones));
  };

  const applyMemberToneDirectInput = (idx: number) => {
    const nextTone = memberToneDirectDraft.trim();
    if (!nextTone) return;
    handleUpdateMember(idx, { toneId: nextTone });
    setMemberToneDirectInputId(null);
    setMemberToneDirectDraft('');
    setActiveVocalTonePopup(null);
  };

  const cancelMemberToneDirectInput = () => {
    setMemberToneDirectInputId(null);
    setMemberToneDirectDraft('');
  };

  useEffect(() => {
    if (!activeVocalTonePopup) return;

    updateMemberTonePopupPos();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setActiveVocalTonePopup(null);
    };

    const handlePointerDown = (event: MouseEvent | TouchEvent) => {
      const target = event.target as HTMLElement | null;
      if (!target) return;
      if (target.closest('[data-member-tone-panel]') || target.closest('[data-tone-trigger]')) return;
      setActiveVocalTonePopup(null);
      setMemberToneDirectInputId(null);
      setMemberToneDirectDraft('');
    };

    const handleWindowChange = () => updateMemberTonePopupPos();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('resize', handleWindowChange);
    window.addEventListener('scroll', handleWindowChange, true);
    document.addEventListener('mousedown', handlePointerDown);
    document.addEventListener('touchstart', handlePointerDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('resize', handleWindowChange);
      window.removeEventListener('scroll', handleWindowChange, true);
      document.removeEventListener('mousedown', handlePointerDown);
      document.removeEventListener('touchstart', handlePointerDown);
    };
  }, [activeVocalTonePopup, updateMemberTonePopupPos]);

  const getModeLabel = (mode: VocalMode) => {
    if (mode === 'solo') return "솔로";
    return "그룹";
  };

  const markVocalManualSelection = () => {
    setIsVocalRandomActive(false);
    setVocalCompositionSource('manual');
  };

  const markVocalEmptySelection = () => {
    setIsVocalRandomActive(false);
    setVocalCompositionSource('empty');
  };

  useEffect(() => {
    if (maleCount + femaleCount === 0 && vocalMembers.length === 0) {
      setIsVocalRandomActive(false);
      setVocalCompositionSource('empty');
    }
  }, [maleCount, femaleCount, vocalMembers.length]);

  const getCombinedDescription = () => {
    if (maleCount === 0 && femaleCount === 0) return "보컬의 구성과 성별을 선택합니다.";
    
    const parts = [];
    parts.push(getModeLabel(vocalMode));
    
    if (maleCount > 0 && femaleCount > 0) parts.push("혼성");
    else if (maleCount > 0) parts.push("남성");
    else if (femaleCount > 0) parts.push("여성");
    
    return parts.join(" ");
  };

  const [contentHeight, setContentHeight] = useState<number | string>('auto');

  useStableContentHeight(contentRef, setContentHeight, [vocalMode, maleCount, femaleCount, vocalMembers, rapEnabled, rapMode, isKoreanEnglishMix, englishMixRatio]);

  const createDefaultMember = (index: number, mode: VocalMode): VocalMember => ({
    id: `member_default_${mode}_${index}_${Date.now()}`,
    gender: 'neutral',
    roles: index === 0 ? ['main'] : index === 1 ? ['lead'] : ['sub'],
  });

  const handleModeClick = (mode: VocalMode) => {
    const nextMode = mode === 'duo' ? 'group' : mode;
    const isModeChanging = vocalMode !== nextMode;
    onModeChange(nextMode);

    if (isModeChanging) {
      onMaleChange(0);
      onFemaleChange(0);
      onMembersChange(nextMode === 'group'
        ? [createDefaultMember(0, nextMode), createDefaultMember(1, nextMode)]
        : [createDefaultMember(0, nextMode)]);
      markVocalEmptySelection();
    }

    onHover({ id: 'vocal-mode', label: 'Vocal Mode', labelKo: getModeLabel(nextMode), description: `${getModeLabel(nextMode)} 모드로 전환합니다.`, _ts: Date.now() });
  };

  const handleGenderToggle = (gender: 'male' | 'female') => {
    if (vocalMode !== 'solo') return;

    const current = vocalMembers[0] || createDefaultMember(0, 'solo');
    const nextGender = current.gender === gender ? 'neutral' : gender;
    onMembersChange([{ ...current, gender: nextGender }]);
    onMaleChange(nextGender === 'male' ? 1 : 0);
    onFemaleChange(nextGender === 'female' ? 1 : 0);
    if (nextGender === 'neutral') markVocalEmptySelection();
    else markVocalManualSelection();

    onHover({ 
      id: gender, 
      label: gender === 'male' ? 'Male' : 'Female', 
      labelKo: gender === 'male' ? '남성' : '여성', 
      description: nextGender === 'neutral'
        ? '성별 지정을 해제하고 성별 미지정 솔로 보컬로 사용합니다.'
        : `${gender === 'male' ? '남성' : '여성'} 솔로 보컬을 선택합니다.`, 
      _ts: Date.now() 
    });
  };

  const handleAddMember = (gender: 'male' | 'female') => {
    if (vocalMode !== 'group') return;

    const neutralIndex = vocalMembers.findIndex((member) => member.gender === 'neutral');
    if (neutralIndex >= 0) {
      const nextMembers = vocalMembers.map((member, index) => index === neutralIndex ? { ...member, gender } : member);
      onMembersChange(nextMembers);
      if (gender === 'male') onMaleChange(maleCount + 1);
      else onFemaleChange(femaleCount + 1);
      markVocalManualSelection();
      return;
    }

    if (vocalMembers.length >= MAX_GROUP_VOCAL_MEMBERS) return;

    const newMember: VocalMember = {
      id: `member_${Date.now()}`,
      gender,
      roles: vocalMembers.length === 0
        ? ['main']
        : vocalMembers.length === 1
          ? ['lead']
          : vocalMembers.length === 2 && isRapLikeGenre(genreHints)
            ? ['rapper']
            : ['sub'],
    };
    onMembersChange([...vocalMembers, newMember]);
    if (gender === 'male') onMaleChange(maleCount + 1);
    else onFemaleChange(femaleCount + 1);
    markVocalManualSelection();
  };

  const handleRemoveMember = (idx: number) => {
    const member = vocalMembers[idx];
    if (!member) return;

    if (vocalMode === 'solo') {
      onMembersChange([createDefaultMember(0, 'solo')]);
      onMaleChange(0);
      onFemaleChange(0);
      markVocalEmptySelection();
      return;
    }

    if (vocalMembers.length <= 2) {
      const nextMembers = vocalMembers.map((item, index) => index === idx
        ? { ...createDefaultMember(index, 'group'), id: item.id }
        : item);
      onMembersChange(nextMembers);
    } else {
      onMembersChange(vocalMembers.filter((_, index) => index !== idx));
    }

    if (member.gender === 'male') onMaleChange(Math.max(0, maleCount - 1));
    if (member.gender === 'female') onFemaleChange(Math.max(0, femaleCount - 1));
    markVocalManualSelection();
  };

  const handleUpdateMember = (idx: number, updates: Partial<VocalMember>) => {
    const newMembers = [...vocalMembers];
    newMembers[idx] = { ...newMembers[idx], ...updates };
    onMembersChange(newMembers);
    markVocalManualSelection();
  };


  const updateMemberCharacter = (idx: number, updates: Partial<NonNullable<VocalMember['character']>>) => {
    const current = vocalMembers[idx]?.character || {};
    handleUpdateMember(idx, {
      character: {
        ...current,
        ...updates,
      },
    });
  };

  const toggleMemberTechnique = (idx: number, techniqueId: string) => {
    const current = vocalMembers[idx]?.character?.techniqueIds || [];
    const next = current.includes(techniqueId)
      ? current.filter((id) => id !== techniqueId)
      : [...current, techniqueId];
    updateMemberCharacter(idx, { techniqueIds: next });
  };

  const getVocalCharacterSummary = (member: VocalMember) => {
    const character = member.character || {};
    const scaleParts = VOCAL_CHARACTER_SCALE_CONFIGS
      .flatMap((config) => {
        const level = getVocalCharacterScaleLevel(character, config);
        const labels: string[] = [];
        if (!isVocalCharacterScaleDefaultLevel(config, level)) labels.push(getVocalCharacterScaleStep(config.key, level)?.labelKo || '');
        if (isVocalCharacterOrnamentConfig(config)) {
          const secondaryLevel = getVocalCharacterOrnamentSecondaryLevel(character, config);
          if (!isVocalCharacterScaleDefaultLevel(config, secondaryLevel)) labels.push(`${config.steps[secondaryLevel - 1]?.labelKo || ''}`);
        }
        return labels.filter(Boolean);
      })
      .filter(Boolean)
      .slice(0, 4);
    const voice = VOCAL_VOICE_TONES.find((item) => item.id === character.voiceToneId)?.labelKo;
    const personality = VOCAL_PERSONALITIES.find((item) => item.id === character.personalityId)?.labelKo;
    const techniques = (character.techniqueIds || [])
      .map((id) => VOCAL_TECHNIQUES.find((item) => item.id === id)?.labelKo)
      .filter(Boolean)
      .slice(0, 2);
    const parts = [...scaleParts, voice, personality, ...techniques].filter(Boolean);
    return parts.length > 0 ? parts.join(' · ') : '연령 / 음역 / 창법 / 박자 / 감정 / 매력';
  };

  const editingVocalMemberIndex = editingVocalMemberId
    ? vocalMembers.findIndex((member) => member.id === editingVocalMemberId)
    : -1;
  const editingVocalMember = editingVocalMemberIndex >= 0 ? vocalMembers[editingVocalMemberIndex] : null;
  const [localVocalCharacterDraft, setLocalVocalCharacterDraft] = useState<NonNullable<VocalMember['character']>>({});
  const initialVocalCharacterRef = useRef<NonNullable<VocalMember['character']>>({});
  const vocalCharacterBackdropPointerDownRef = useRef(false);
  const vocalCharacterCloseFromHistoryRef = useRef(false);
  const vocalCharacterTouchStartYRef = useRef<number | null>(null);

  const stopVocalCharacterScrollChaining = (element: HTMLElement, deltaY: number, preventDefault: () => void) => {
    const canScroll = element.scrollHeight > element.clientHeight + 1;
    if (!canScroll) {
      preventDefault();
      return;
    }

    const atTop = element.scrollTop <= 0;
    const atBottom = Math.ceil(element.scrollTop + element.clientHeight) >= element.scrollHeight;
    if ((atTop && deltaY < 0) || (atBottom && deltaY > 0)) {
      preventDefault();
    }
  };

  const handleVocalCharacterWheel = (event: React.WheelEvent<HTMLDivElement>) => {
    event.stopPropagation();
    stopVocalCharacterScrollChaining(event.currentTarget, event.deltaY, () => event.preventDefault());
  };

  const handleVocalCharacterTouchStart = (event: React.TouchEvent<HTMLDivElement>) => {
    vocalCharacterTouchStartYRef.current = event.touches[0]?.clientY ?? null;
  };

  const handleVocalCharacterTouchMove = (event: React.TouchEvent<HTMLDivElement>) => {
    event.stopPropagation();
    const startY = vocalCharacterTouchStartYRef.current;
    const currentY = event.touches[0]?.clientY ?? null;
    if (startY === null || currentY === null) return;
    stopVocalCharacterScrollChaining(event.currentTarget, startY - currentY, () => event.preventDefault());
  };

  const blockVocalCharacterOuterScroll = (event: React.WheelEvent<HTMLDivElement> | React.TouchEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  useEffect(() => {
    onModalStateChange?.(!!editingVocalMember);
  }, [editingVocalMember, onModalStateChange]);

  useEffect(() => {
    const handleCloseStudioModals = () => {
      setEditingVocalMemberId(null);
      setActiveVocalTonePopup(null);
      vocalCharacterBackdropPointerDownRef.current = false;
      vocalCharacterCloseFromHistoryRef.current = false;
    };
    window.addEventListener(SORIDRAW_CLOSE_STUDIO_MODALS_EVENT, handleCloseStudioModals);
    return () => window.removeEventListener(SORIDRAW_CLOSE_STUDIO_MODALS_EVENT, handleCloseStudioModals);
  }, []);

  const getVocalCharacterSignature = useCallback((character?: VocalMember['character']) => JSON.stringify({
    voiceToneId: character?.voiceToneId || '',
    personalityId: character?.personalityId || '',
    techniqueIds: [...(character?.techniqueIds || [])].sort(),
    ageLevel: character?.ageLevel || '',
    rangeLevel: character?.rangeLevel || '',
    deliveryLevel: character?.deliveryLevel || '',
    rhythmLevel: character?.rhythmLevel || '',
    emotionLevel: character?.emotionLevel || '',
    textureLevel: character?.textureLevel || '',
    charmLevel: character?.charmLevel || '',
    ornamentLevel: character?.ornamentLevel || '',
    ornamentSecondaryLevel: (character as any)?.ornamentSecondaryLevel || '',
  }), []);

  const hasNonDefaultVocalCharacterScale = VOCAL_CHARACTER_SCALE_CONFIGS.some((config) => {
    const value = Number(localVocalCharacterDraft[config.key]);
    const hasMain = Number.isFinite(value) && !isVocalCharacterScaleDefaultLevel(config, Math.min(config.steps.length, Math.max(1, Math.round(value))));
    if (!isVocalCharacterOrnamentConfig(config)) return hasMain;
    const secondaryValue = Number((localVocalCharacterDraft as any).ornamentSecondaryLevel);
    const hasSecondary = Number.isFinite(secondaryValue) && !isVocalCharacterScaleDefaultLevel(config, Math.min(config.steps.length, Math.max(1, Math.round(secondaryValue))));
    return hasMain || hasSecondary;
  });

  const hasVocalCharacterChanges = getVocalCharacterSignature(localVocalCharacterDraft) !== getVocalCharacterSignature(initialVocalCharacterRef.current);
  const hasVocalCharacterSelection = Boolean(
    hasNonDefaultVocalCharacterScale ||
    localVocalCharacterDraft.voiceToneId ||
    localVocalCharacterDraft.personalityId ||
    (localVocalCharacterDraft.techniqueIds || []).length > 0
  );

  const closeVocalCharacterEditor = useCallback(() => {
    if (window.history.state?.vocalCharacterEditor && !vocalCharacterCloseFromHistoryRef.current) {
      vocalCharacterCloseFromHistoryRef.current = true;
      window.history.back();
      return;
    }
    setEditingVocalMemberId(null);
  }, []);

  useEffect(() => {
    if (!editingVocalMember) return;
    const initialCharacter = { ...(editingVocalMember.character || {}) };
    if (initialCharacter.techniqueIds) {
      initialCharacter.techniqueIds = [...initialCharacter.techniqueIds];
    }
    initialVocalCharacterRef.current = initialCharacter;
    setLocalVocalCharacterDraft(initialCharacter);
    vocalCharacterCloseFromHistoryRef.current = false;

    try {
      window.history.pushState({ ...(window.history.state || {}), vocalCharacterEditor: true }, '');
    } catch {
      // ignore history errors in embedded preview environments
    }

    const handlePopState = () => {
      vocalCharacterCloseFromHistoryRef.current = true;
      setEditingVocalMemberId(null);
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        closeVocalCharacterEditor();
      }
    };

    window.addEventListener('popstate', handlePopState);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('popstate', handlePopState);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [editingVocalMember, closeVocalCharacterEditor]);

  const updateLocalVocalCharacter = useCallback((updates: Partial<NonNullable<VocalMember['character']>>) => {
    setLocalVocalCharacterDraft((current) => ({
      ...current,
      ...updates,
    }));
  }, []);

  const handleVocalCharacterDualSliderDragStart = useCallback((event: React.PointerEvent<HTMLButtonElement>, config: VocalCharacterScaleConfig, fieldKey: 'ornamentLevel' | 'ornamentSecondaryLevel') => {
    event.preventDefault();
    event.stopPropagation();

    const track = event.currentTarget.closest('[data-vocal-character-dual-track]') as HTMLElement | null;
    if (!track) return;

    const updateFromClientX = (clientX: number) => {
      const rect = track.getBoundingClientRect();
      const ratio = rect.width > 0 ? Math.max(0, Math.min(1, (clientX - rect.left) / rect.width)) : 0;
      const nextLevel = Math.round(ratio * (config.steps.length - 1)) + 1;
      updateLocalVocalCharacter({ [fieldKey]: nextLevel } as Partial<NonNullable<VocalMember['character']>>);
    };

    updateFromClientX(event.clientX);

    const handlePointerMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      updateFromClientX(moveEvent.clientX);
    };

    const handlePointerEnd = () => {
      document.removeEventListener('pointermove', handlePointerMove, true);
      document.removeEventListener('pointerup', handlePointerEnd, true);
      document.removeEventListener('pointercancel', handlePointerEnd, true);
      document.body.style.userSelect = '';
    };

    document.body.style.userSelect = 'none';
    document.addEventListener('pointermove', handlePointerMove, true);
    document.addEventListener('pointerup', handlePointerEnd, true);
    document.addEventListener('pointercancel', handlePointerEnd, true);
  }, [updateLocalVocalCharacter]);

  const toggleLocalVocalTechnique = useCallback((techniqueId: string) => {
    setLocalVocalCharacterDraft((current) => {
      const techniqueIds = current.techniqueIds || [];
      const next = techniqueIds.includes(techniqueId)
        ? techniqueIds.filter((id) => id !== techniqueId)
        : [...techniqueIds, techniqueId];
      return { ...current, techniqueIds: next };
    });
  }, []);

  const clearLocalVocalCharacter = useCallback(() => {
    setLocalVocalCharacterDraft({});
  }, []);

  const applyVocalCharacterAndClose = useCallback(() => {
    if (!editingVocalMember || editingVocalMemberIndex < 0) return;
    const normalizedCharacter: NonNullable<VocalMember['character']> = {
      ...(localVocalCharacterDraft.voiceToneId ? { voiceToneId: localVocalCharacterDraft.voiceToneId } : {}),
      ...(localVocalCharacterDraft.personalityId ? { personalityId: localVocalCharacterDraft.personalityId } : {}),
      ...((localVocalCharacterDraft.techniqueIds || []).length > 0 ? { techniqueIds: localVocalCharacterDraft.techniqueIds } : {}),
    };
    VOCAL_CHARACTER_SCALE_CONFIGS.forEach((config) => {
      const value = Number(localVocalCharacterDraft[config.key]);
      const safeValue = Math.min(config.steps.length, Math.max(1, Math.round(value)));
      if (Number.isFinite(value) && !isVocalCharacterScaleDefaultLevel(config, safeValue)) {
        (normalizedCharacter as any)[config.key] = safeValue;
      }
      if (isVocalCharacterOrnamentConfig(config)) {
        const secondaryValue = Number((localVocalCharacterDraft as any).ornamentSecondaryLevel);
        const safeSecondaryValue = Math.min(config.steps.length, Math.max(1, Math.round(secondaryValue)));
        if (Number.isFinite(secondaryValue) && !isVocalCharacterScaleDefaultLevel(config, safeSecondaryValue)) {
          (normalizedCharacter as any).ornamentSecondaryLevel = safeSecondaryValue;
        }
      }
    });
    handleUpdateMember(editingVocalMemberIndex, {
      character: Object.keys(normalizedCharacter).length > 0 ? normalizedCharacter : undefined,
    });
    closeVocalCharacterEditor();
  }, [closeVocalCharacterEditor, editingVocalMember, editingVocalMemberIndex, handleUpdateMember, localVocalCharacterDraft]);

  const filteredTones = vocalTones.filter(t => {
    const target = t.genderTarget as string;
    if (target === 'any' || target === 'unisex') return true;
    
    if (maleCount > 0 && femaleCount > 0) {
      return target === 'unisex' || target === 'any' || target === 'group';
    }
    if (maleCount > 0) {
      return target === 'male' || target === 'any' || (vocalMode === 'group' && target === 'group');
    }
    if (femaleCount > 0) {
      return target === 'female' || target === 'any' || (vocalMode === 'group' && target === 'group');
    }
    
    return true;
  });

  const handleRandomVocal = () => {
    if (isLocked) {
      onHover({ id: 'vocal-random-locked', label: 'Locked', labelKo: '보컬 잠금', description: '보컬 메뉴가 잠겨 있어 랜덤을 적용하지 않습니다.', _ts: Date.now() });
      return;
    }

    const activeMembers = vocalMembers.length > 0
      ? vocalMembers
      : [createDefaultMember(0, vocalMode)];
    const nextMembers = activeMembers.map((member, index) => ({
      ...member,
      // Random changes the character only. Gender, member count, mode, and roles stay fixed.
      character: buildRandomVocalCharacter(member.gender, index, activeMembers.length, genreHints),
    }));

    onMembersChange(nextMembers);
    setIsVocalRandomActive(true);
    setVocalCompositionSource(vocalCompositionSource === 'empty' ? 'manual' : vocalCompositionSource);
    onHover({
      id: 'vocal-random',
      label: 'Random Vocal Character',
      labelKo: '보컬 캐릭터 랜덤',
      description: '현재 성별·인원·역할은 그대로 두고 보컬 캐릭터만 랜덤 적용했습니다.',
      _ts: Date.now(),
    });
  };

  const cycleRapMode = () => {
    const nextMode: RapMode = rapMode === 'auto' ? 'off' : rapMode === 'off' ? 'on' : 'auto';
    onRapModeChange(nextMode);
    onRapChange(nextMode === 'on');
    onHover({
      id: 'vocal-rap-mode',
      label: `Rap ${nextMode.toUpperCase()}`,
      labelKo: `랩 ${nextMode.toUpperCase()}`,
      description: nextMode === 'auto'
        ? '래퍼 역할·장르·섹션 구조에 맞을 때만 랩을 적용합니다.'
        : nextMode === 'on'
          ? '래퍼 역할이 없어도 랩 구간을 적극적으로 적용합니다.'
          : '래퍼 역할이 있어도 랩 구간을 만들지 않습니다.',
      _ts: Date.now(),
    });
  };

  const getVocalModeTooltip = (mode: VocalMode): CategoryItem => {
    const modeInfo: Record<VocalMode, CategoryItem> = {
      solo: { id: 'vocal-mode-solo', label: 'Solo', labelKo: '솔로', description: '혼자서 노래하는 솔로 보컬을 선택합니다.' },
      duo: { id: 'vocal-mode-duo', label: 'Group', labelKo: '그룹', description: '두 명 이상을 캐릭터별로 설정합니다.' },
      group: { id: 'vocal-mode-group', label: 'Group', labelKo: '그룹', description: '두 명 이상을 캐릭터별로 설정합니다.' },
    };
    return modeInfo[mode] || modeInfo.group;
  };

  return (
    <div data-studio-menu="vocal" className="soridraw-expand-card soridraw-studio-menu-card soridraw-studio-shadow-surface bg-[var(--card-bg)] rounded-3xl p-5 pb-10 border border-[var(--home-card-border)] flex flex-col h-full relative overflow-visible">
      <div className="soridraw-card-header relative mb-4 flex items-center justify-between">
        <div className="soridraw-card-header-title flex items-center gap-2">
          <h3 
            onMouseEnter={() => setShowTitleTooltip(true)}
            onMouseLeave={() => setShowTitleTooltip(false)}
            className="text-[22px] font-bold text-[var(--text-primary)] flex items-center gap-2.5 cursor-help"
          >
            <span className="w-1.5 h-6 bg-[#FFB400] rounded-full" />
            보컬
          </h3>
        </div>

        <div className="soridraw-card-header-actions flex items-center gap-2">
          <button
            type="button"
            onClick={cycleRapMode}
            onMouseEnter={() => onHover({
              id: 'vocal-rap-mode',
              label: `Rap ${rapMode.toUpperCase()}`,
              labelKo: `랩 ${rapMode.toUpperCase()}`,
              description: rapMode === 'auto'
                ? '래퍼 역할·장르·섹션 구조에 맞을 때만 랩을 적용합니다. 클릭하면 OFF로 전환됩니다.'
                : rapMode === 'on'
                  ? '래퍼 역할이 없어도 랩 구간을 적극적으로 적용합니다. 클릭하면 AUTO로 전환됩니다.'
                  : '래퍼 역할이 있어도 랩 구간을 만들지 않습니다. 클릭하면 ON으로 전환됩니다.'
            })}
            onMouseLeave={() => onHover(null)}
            className={cn(
              "h-10 px-3 rounded-xl transition-all border shadow-btn flex items-center gap-1.5 text-[11px] font-black",
              rapMode === 'on'
                ? "bg-[#FFB400] text-[#171717] border-black/20 soridraw-selected-strong"
                : rapMode === 'auto'
                  ? "bg-btn-bg text-[#FFB400] border-btn-border hover:bg-btn-hover"
                  : "bg-btn-bg text-[var(--text-secondary)] border-btn-border hover:bg-btn-hover"
            )}
            title={`랩 모드 ${rapMode.toUpperCase()} · 클릭하여 AUTO → OFF → ON 순환`}
            aria-label={`랩 모드 ${rapMode.toUpperCase()}`}
          >
            <Mic2 className="w-3.5 h-3.5" />
            <span>랩 {rapMode.toUpperCase()}</span>
          </button>
          {onToggleLock && (
            <button
              type="button"
              onClick={onToggleLock}
              onMouseEnter={() => onHover({ id: 'vocal-lock', label: isLocked ? 'Unlock menu' : 'Lock menu', labelKo: isLocked ? '잠금 해제' : '메뉴 잠금', description: isLocked ? '보컬 메뉴를 랜덤 선택에 다시 포함합니다.' : '현재 보컬 설정을 유지하고 랜덤 선택에서 제외합니다.' })}
              onMouseLeave={() => onHover(null)}
              onTouchStart={() => onLongPressStart({ id: 'vocal-lock', label: isLocked ? 'Unlock menu' : 'Lock menu', labelKo: isLocked ? '잠금 해제' : '메뉴 잠금', description: isLocked ? '보컬 메뉴를 랜덤 선택에 다시 포함합니다.' : '현재 보컬 설정을 유지하고 랜덤 선택에서 제외합니다.' })}
              onTouchEnd={onLongPressEnd}
              onTouchCancel={onLongPressEnd}
              className={cn(
                "p-2.5 rounded-xl transition-all border border-btn-border shadow-btn",
                isLocked
                  ? "bg-[#FFB400] text-[#171717] font-black border-black/20 soridraw-selected-strong shadow-[0_10px_24px_rgba(0,0,0,0.16)]"
                  : "bg-btn-bg text-[var(--text-secondary)] hover:bg-btn-hover"
              )}
              title={isLocked ? '잠금 해제' : '메뉴 잠금'}
              aria-label={isLocked ? '보컬 잠금 해제' : '보컬 잠금'}
            >
              {isLocked ? <Lock className="w-4 h-4" /> : <Unlock className="w-4 h-4" />}
            </button>
          )}
          <button
            type="button"
            onClick={handleRandomVocal}
            onMouseEnter={() => onHover({ id: 'vocal-random', label: 'Random Vocal', labelKo: '보컬 랜덤', description: '현재 성별·인원·역할은 유지하고 보컬 캐릭터만 랜덤 적용합니다.' })}
            onMouseLeave={() => onHover(null)}
            onTouchStart={() => onLongPressStart({ id: 'vocal-random', label: 'Random Vocal', labelKo: '보컬 랜덤', description: '현재 성별·인원·역할은 유지하고 보컬 캐릭터만 랜덤 적용합니다.' })}
            onTouchEnd={onLongPressEnd}
            onTouchCancel={onLongPressEnd}
            className={cn(
              "p-2.5 rounded-xl transition-all border shadow-btn",
              isVocalRandomActive
                ? "bg-[#FFB400] text-[#171717] font-black border-black/20 soridraw-selected-strong shadow-[0_10px_24px_rgba(0,0,0,0.16)]"
                : "bg-btn-bg text-[var(--text-secondary)] border-btn-border hover:bg-btn-hover"
            )}
            title="보컬 랜덤"
            aria-label="보컬 랜덤"
            aria-pressed={isVocalRandomActive}
          >
            <Dices className="w-4 h-4" />
          </button>
          <button
            onClick={() => {
              markVocalEmptySelection();
              onClear();
            }}
            onMouseEnter={() => onHover({ id: 'vocal-clear', label: 'Reset', labelKo: '초기화', description: '보컬 설정을 초기화합니다.' })}
            onMouseLeave={() => onHover(null)}
            onTouchStart={() => onLongPressStart({ id: 'vocal-clear', label: 'Reset', labelKo: '초기화', description: '보컬 설정을 초기화합니다.' })}
            onTouchEnd={onLongPressEnd}
            onTouchCancel={onLongPressEnd}
            className={cn(
              "p-2.5 rounded-xl transition-all border shadow-btn",
              (maleCount > 0 || femaleCount > 0)
                ? "bg-[#FFB400]/20 text-[#FFD36A] border-black/20 hover:bg-[#FFB400]/30" 
                : "bg-btn-bg text-[var(--text-secondary)] border-btn-border hover:bg-btn-hover"
            )}
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>

        <AnimatePresence>
          {showTitleTooltip && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 10 }}
              className="absolute top-full left-0 mt-2 z-50 px-3 py-2 rounded-xl bg-[var(--card-bg)] border border-black/20/30 shadow-2xl w-48 pointer-events-none"
            >
              <p className="text-[11px] text-[var(--text-secondary)] leading-snug">{getCombinedDescription()}</p>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <div className={cn(
        "flex flex-col flex-1 overflow-visible transition-all duration-500 ease-in-out",
        (vocalMembers.length > 0 || maleCount > 0 || femaleCount > 0 || vocalMode === 'group') ? "justify-start" : "justify-center"
      )}>
        <motion.div 
          animate={{ height: contentHeight }}
          transition={{ duration: 0.25, ease: "easeOut" }}
          className="soridraw-expand-content overflow-hidden min-h-[76px]"
        >
          <div ref={contentRef} className="space-y-2 mt-0">
            {/* Mode Selection */}
          <div className="flex gap-1 bg-btn-bg p-1 rounded-xl border border-btn-border shadow-btn">
            {(['solo', 'group'] as VocalMode[]).map((mode) => (
              <button
                key={mode}
                data-soridraw-selected={vocalMode === mode ? 'true' : 'false'}
                aria-pressed={vocalMode === mode}
                onClick={() => handleModeClick(mode)}
                onMouseEnter={() => onHover(getVocalModeTooltip(mode))}
                onMouseLeave={() => onHover(null)}
                onTouchStart={() => onLongPressStart(getVocalModeTooltip(mode))}
                onTouchEnd={onLongPressEnd}
                onTouchCancel={onLongPressEnd}
                className={cn(
                  "flex-1 py-2.5 rounded-xl text-[14px] font-bold transition-all",
                  vocalMode === mode 
                    ? "bg-[#FFB400] text-[#171717] font-black shadow-md" 
                    : "text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-btn-hover"
                )}
              >
                {getModeLabel(mode)}
              </button>
            ))}
          </div>

          {/* Gender Selection */}
          {vocalMode === 'group' ? (
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => handleAddMember('male')}
                disabled={vocalMembers.length >= MAX_GROUP_VOCAL_MEMBERS && !vocalMembers.some((member) => member.gender === 'neutral')}
                onMouseEnter={() => onHover({ id: 'add-male', label: 'Add Male Member', labelKo: '남성 멤버 추가', description: vocalMembers.some((member) => member.gender === 'neutral') ? '성별이 없는 기본 보컬에 남성 성별을 지정합니다.' : '남성 보컬 멤버를 1명 추가합니다.' })}
                onMouseLeave={() => onHover(null)}
                onTouchStart={() => onLongPressStart({ id: 'add-male', label: 'Add Male Member', labelKo: '남성 멤버 추가', description: vocalMembers.some((member) => member.gender === 'neutral') ? '성별이 없는 기본 보컬에 남성 성별을 지정합니다.' : '남성 보컬 멤버를 1명 추가합니다.' })}
                onTouchEnd={onLongPressEnd}
                onTouchCancel={onLongPressEnd}
                className={cn(
                  "py-3 px-2 rounded-2xl text-[14px] font-bold transition-all border flex items-center justify-center gap-2.5",
                  vocalMembers.length < MAX_GROUP_VOCAL_MEMBERS || vocalMembers.some((member) => member.gender === 'neutral')
                    ? "bg-blue-600/10 border-blue-500/20 text-blue-400 hover:bg-blue-600/20"
                    : "bg-btn-bg border-btn-border text-[var(--text-secondary)] opacity-50 cursor-not-allowed"
                )}
              >
                <Plus className="w-3.5 h-3.5" />
                남성 멤버 추가
              </button>
              <button
                onClick={() => handleAddMember('female')}
                disabled={vocalMembers.length >= MAX_GROUP_VOCAL_MEMBERS && !vocalMembers.some((member) => member.gender === 'neutral')}
                onMouseEnter={() => onHover({ id: 'add-female', label: 'Add Female Member', labelKo: '여성 멤버 추가', description: vocalMembers.some((member) => member.gender === 'neutral') ? '성별이 없는 기본 보컬에 여성 성별을 지정합니다.' : '여성 보컬 멤버를 1명 추가합니다.' })}
                onMouseLeave={() => onHover(null)}
                onTouchStart={() => onLongPressStart({ id: 'add-female', label: 'Add Female Member', labelKo: '여성 멤버 추가', description: vocalMembers.some((member) => member.gender === 'neutral') ? '성별이 없는 기본 보컬에 여성 성별을 지정합니다.' : '여성 보컬 멤버를 1명 추가합니다.' })}
                onTouchEnd={onLongPressEnd}
                onTouchCancel={onLongPressEnd}
                className={cn(
                  "py-3 px-2 rounded-2xl text-[14px] font-bold transition-all border flex items-center justify-center gap-2.5",
                  vocalMembers.length < MAX_GROUP_VOCAL_MEMBERS || vocalMembers.some((member) => member.gender === 'neutral')
                    ? "bg-pink-600/10 border-pink-500/20 text-pink-400 hover:bg-pink-600/20"
                    : "bg-btn-bg border-btn-border text-[var(--text-secondary)] opacity-50 cursor-not-allowed"
                )}
              >
                <Plus className="w-3.5 h-3.5" />
                여성 멤버 추가
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-2">
              <button
                data-soridraw-selected={maleCount > 0 ? 'true' : 'false'}
                aria-pressed={maleCount > 0}
                onClick={() => handleGenderToggle('male')}
                onMouseEnter={() => onHover({ id: 'male', label: 'Male', labelKo: '남성', description: '남성 보컬을 선택합니다.' })}
                onMouseLeave={() => onHover(null)}
                onTouchStart={() => onLongPressStart({ id: 'male', label: 'Male', labelKo: '남성', description: '남성 보컬을 선택합니다.' })}
                onTouchEnd={onLongPressEnd}
                onTouchCancel={onLongPressEnd}
                className={cn(
                  "py-3.5 px-3 rounded-2xl text-[15px] font-bold transition-all border flex items-center justify-center gap-2.5 shadow-btn",
                  maleCount > 0
                    ? "bg-blue-600/20 border-blue-500/40 text-blue-400"
                    : "bg-btn-bg border-btn-border text-[var(--text-secondary)] hover:bg-btn-hover"
                )}
              >
                <span className={cn("w-2 h-2 rounded-full", maleCount > 0 ? "bg-blue-400" : "bg-[var(--border-color)]")} />
                남성
              </button>
              <button
                data-soridraw-selected={femaleCount > 0 ? 'true' : 'false'}
                aria-pressed={femaleCount > 0}
                onClick={() => handleGenderToggle('female')}
                onMouseEnter={() => onHover({ id: 'female', label: 'Female', labelKo: '여성', description: '여성 보컬을 선택합니다.' })}
                onMouseLeave={() => onHover(null)}
                onTouchStart={() => onLongPressStart({ id: 'female', label: 'Female', labelKo: '여성', description: '여성 보컬을 선택합니다.' })}
                onTouchEnd={onLongPressEnd}
                onTouchCancel={onLongPressEnd}
                className={cn(
                  "py-3.5 px-3 rounded-2xl text-[15px] font-bold transition-all border flex items-center justify-center gap-2.5 shadow-btn",
                  femaleCount > 0
                    ? "bg-pink-600/20 border-pink-500/40 text-pink-400"
                    : "bg-btn-bg border-btn-border text-[var(--text-secondary)] hover:bg-btn-hover"
                )}
              >
                <span className={cn("w-2 h-2 rounded-full", femaleCount > 0 ? "bg-pink-400" : "bg-[var(--border-color)]")} />
                여성
              </button>
            </div>
          )}


          {/* Global vocal emotion direction removed.
              Vocal emotion/attitude is now handled per character through 성격. */}

          {/* Member Roles */}
          {vocalMembers.length > 0 && (
            <div className="space-y-1.5 pt-1.5 border-t border-[var(--border-color)]">
              <div className="flex items-center justify-between px-1">
                <p className="text-[10px] font-bold text-[var(--text-secondary)] uppercase tracking-wider">멤버 ({vocalMembers.length}/{vocalMode === 'solo' ? 1 : MAX_GROUP_VOCAL_MEMBERS})</p>
                <span className="text-[9px] text-[var(--text-secondary)] opacity-50">연령 · 음역 · 창법 · 기교</span>
              </div>
              <div className={cn("soridraw-vocal-member-grid grid gap-2 max-h-[300px] overflow-y-auto pr-1 custom-scrollbar items-start", vocalMode === 'solo' ? "grid-cols-1" : "grid-cols-2")}>
                {vocalMembers.map((member, idx) => {
                  const memberLetter = String.fromCharCode(65 + idx);
                  const memberDisplayName = member.gender === 'male'
                    ? `남성${memberLetter}`
                    : member.gender === 'female'
                      ? `여성${memberLetter}`
                      : `보컬${memberLetter}`;
                  const memberAccent = member.gender === 'male'
                    ? { dot: 'bg-blue-400', text: 'text-[#4B6280]', hoverBorder: 'hover:border-[#4B6280]/45 hover:bg-[#4B6280]/5', hoverText: 'group-hover/character:text-[#4B6280]' }
                    : member.gender === 'female'
                      ? { dot: 'bg-pink-400', text: 'text-[#73495D]', hoverBorder: 'hover:border-[#73495D]/45 hover:bg-[#73495D]/5', hoverText: 'group-hover/character:text-[#73495D]' }
                      : { dot: 'bg-[#FFB400]', text: 'text-[#D89A00]', hoverBorder: 'hover:border-[#FFB400]/45 hover:bg-[#FFB400]/5', hoverText: 'group-hover/character:text-[#FFB400]' };
                  const roleLabels: Record<VocalRole, { label: string, labelKo: string, description: string }> = {
                    main: { label: 'Main Vocal', labelKo: '메인', description: '곡의 중심이 되는 메인 보컬 역할을 수행합니다.' },
                    lead: { label: 'Lead Vocal', labelKo: '리드', description: '메인 보컬을 보조하며 곡의 흐름을 이끄는 역할을 수행합니다.' },
                    sub: { label: 'Sub Vocal', labelKo: '서브', description: '곡의 풍성함을 더해주는 서브 보컬 역할을 수행합니다.' },
                    rapper: { label: 'Rapper', labelKo: '래퍼', description: '곡의 랩 파트를 담당하는 래퍼 역할을 수행합니다.' }
                  };

                  return (
                  <div key={member.id} className="bg-btn-bg rounded-xl p-2 border border-btn-border relative group/member shadow-sm">
                    <div className="soridraw-vocal-member-header flex items-center justify-between gap-2 mb-1.5">
                      <div className="soridraw-vocal-member-heading flex min-w-0 flex-1 items-center gap-2">
                        <div className="soridraw-vocal-member-identity flex min-w-0 items-center gap-2">
                          <span className={cn(
                            "w-2 h-2 rounded-full shrink-0",
                            memberAccent.dot
                          )} />
                          <span className="shrink-0 text-xs font-bold text-[var(--text-primary)]">
                            {memberDisplayName}
                          </span>
                          <span className="h-4 w-px shrink-0 bg-[var(--border-color)]" />
                        </div>
                        <div className="soridraw-vocal-role-buttons flex min-w-0 flex-nowrap items-center justify-center gap-1">
                          {(['main', 'lead', 'sub', 'rapper'] as VocalRole[]).map(role => {
                            const isActive = member.roles.includes(role);
                            const isRoleLimitReached = member.roles.length >= 2;
                            const info = roleLabels[role];
                            
                            return (
                              <button
                                key={role}
                                data-soridraw-selected={isActive ? 'true' : 'false'}
                                aria-pressed={isActive}
                                onClick={() => {
                                  if (isActive) {
                                    handleUpdateMember(idx, { roles: member.roles.filter(r => r !== role) });
                                    return;
                                  }
                                  if (isRoleLimitReached) return;
                                  handleUpdateMember(idx, { roles: [...member.roles, role] });
                                }}
                                onMouseEnter={() => onHover({ id: `role-${role}`, ...info })}
                                onMouseLeave={() => onHover(null)}
                                onTouchStart={() => onLongPressStart({ id: `role-${role}`, ...info })}
                                onTouchEnd={onLongPressEnd}
                                onTouchCancel={onLongPressEnd}
                                className={cn(
                                  "soridraw-vocal-role-button px-1.5 py-0.5 rounded-md text-[10px] leading-4 whitespace-nowrap font-bold transition-all border",
                                  isActive
                                    ? "bg-[#FFB400]/20 border-black/20 text-[#FFD36A]"
                                    : isRoleLimitReached
                                      ? "bg-btn-bg border-btn-border text-[var(--text-secondary)] opacity-45 cursor-not-allowed"
                                      : "bg-btn-bg border-btn-border text-[var(--text-secondary)] hover:bg-btn-hover"
                                )}
                              >
                                {info.labelKo}
                              </button>
                            );
                          })}
                          {/* Legacy 목소리(기본) tone selector is hidden.
                              If no member tone is selected, Gemini keeps using the existing genre-based recommended vocal tone. */}
                        </div>
                      </div>
                      
                      {(vocalMode === 'group' || vocalMode === 'solo') && (
                        <button
                          onClick={() => handleRemoveMember(idx)}
                          onMouseEnter={() => onHover({ id: `remove-member-${idx}`, label: 'Remove Member', labelKo: '멤버 삭제', description: vocalMode === 'solo' ? '선택한 솔로 보컬을 해제합니다.' : '이 멤버를 삭제합니다. 마지막 멤버까지 삭제하면 랜덤 그룹 보컬로 적용됩니다.' })}
                          onMouseLeave={() => onHover(null)}
                          onTouchStart={() => onLongPressStart({ id: `remove-member-${idx}`, label: 'Remove Member', labelKo: '멤버 삭제', description: vocalMode === 'solo' ? '선택한 솔로 보컬을 해제합니다.' : '이 멤버를 삭제합니다. 마지막 멤버까지 삭제하면 랜덤 그룹 보컬로 적용됩니다.' })}
                          onTouchEnd={onLongPressEnd}
                          onTouchCancel={onLongPressEnd}
                          className="soridraw-vocal-member-remove p-1.5 rounded-md text-[var(--text-secondary)] hover:text-red-400 hover:bg-red-400/10 transition-all opacity-100"
                        >
                          <X className="w-[18px] h-[18px]" />
                        </button>
                      )}
                    </div>

                    <div className="space-y-1.5">
                      <button
                        type="button"
                        onClick={() => {
                          onModalStateChange?.(true);
                          setEditingVocalMemberId(member.id);
                        }}
                        className={cn(
                          "soridraw-vocal-character-launcher w-full rounded-xl border border-[var(--border-color)] bg-[var(--card-bg)]/45 p-3 text-left transition-all group/character",
                          memberAccent.hoverBorder
                        )}
                      >
                        <div className="flex items-center justify-between gap-3">
                          <div className="min-w-0">
                            <div className="flex items-center gap-2">
                              <span className={cn(
                                "text-[12px] font-black tracking-tight",
                                memberAccent.text
                              )}>보컬 캐릭터 만들기</span>
                            </div>
                            <div
                              className="vocal-character-horizontal-scroll mt-1 max-w-full overflow-x-auto overflow-y-hidden whitespace-nowrap pb-[3px] text-[12px] font-bold text-[var(--text-primary)] cursor-grab active:cursor-grabbing touch-pan-x select-none"
                              onMouseDown={(event) => {
                                event.stopPropagation();
                                const target = event.currentTarget;
                                const startX = event.pageX;
                                const startScrollLeft = target.scrollLeft;
                                let didDrag = false;

                                const onMove = (moveEvent: MouseEvent) => {
                                  const deltaX = moveEvent.pageX - startX;
                                  if (Math.abs(deltaX) > 3) didDrag = true;
                                  target.scrollLeft = startScrollLeft - deltaX;
                                };

                                const onUp = () => {
                                  if (didDrag) target.dataset.dragged = 'true';
                                  document.removeEventListener('mousemove', onMove);
                                  document.removeEventListener('mouseup', onUp);
                                };

                                document.addEventListener('mousemove', onMove);
                                document.addEventListener('mouseup', onUp);
                              }}
                              onClick={(event) => {
                                const target = event.currentTarget;
                                if (target.dataset.dragged === 'true') {
                                  event.preventDefault();
                                  event.stopPropagation();
                                  delete target.dataset.dragged;
                                }
                              }}
                            >
                              {getVocalCharacterSummary(member)}
                            </div>
                          </div>
                          <div className={cn(
                            "shrink-0 p-1 text-[var(--text-secondary)] transition-colors",
                            memberAccent.hoverText
                          )}>
                            <Edit2 className="w-[22px] h-[22px]" />
                          </div>
                        </div>
                      </button>

                      <AnimatePresence>
                        {activeVocalTonePopup === member.id && (
                          <Portal>
                            <motion.div
                              data-member-tone-panel
                              initial={{ opacity: 1, y: 0 }}
                              animate={{ opacity: 1, y: 0 }}
                              exit={{ opacity: 1, y: 0 }}
                              transition={{ duration: 0 }}
                              className="fixed z-[10050] overflow-hidden rounded-xl border border-[var(--border-color)] bg-[#050505] shadow-2xl shadow-black/60"
                              style={{
                                top: vocalTonePopupPos.top,
                                left: vocalTonePopupPos.left,
                                width: vocalTonePopupPos.width,
                                maxHeight: vocalTonePopupPos.maxHeight,
                              }}
                            >
                              <div className="overflow-y-auto custom-scrollbar p-1.5 space-y-1 bg-[#050505]" style={{ maxHeight: vocalTonePopupPos.maxHeight }}>
                                <button
                                  type="button"
                                  onClick={() => { handleUpdateMember(idx, { toneId: undefined }); setMemberToneDirectInputId(null); setMemberToneDirectDraft(''); setActiveVocalTonePopup(null); }}
                                  className={cn(
                                    "w-full text-left px-2.5 py-1.5 rounded-lg text-[12px] font-bold transition-all border",
                                    !member.toneId
                                      ? "bg-[#FFB400] text-[#171717] font-black border-black/20 shadow-lg shadow-[#FFB400]/20"
                                      : "bg-[#1f1f1f] border-[#3a3a3a] text-[var(--text-secondary)] hover:bg-[#2a2a2a] hover:text-[#FFD36A]"
                                  )}
                                >
                                  <div className="flex items-center justify-between gap-3">
                                    <span>기본 추천 사용</span>
                                    {!member.toneId && <Check className="w-3.5 h-3.5 shrink-0" />}
                                  </div>
                                </button>

                                {memberToneDirectInputId === member.id ? (
                                  <div
                                    className="rounded-lg border border-black/20 bg-[#111] p-2 space-y-2"
                                    onClick={(e) => e.stopPropagation()}
                                    onPointerDown={(e) => e.stopPropagation()}
                                  >
                                    <input
                                      value={memberToneDirectDraft}
                                      onChange={(e) => setMemberToneDirectDraft(e.target.value)}
                                      onKeyDown={(e) => {
                                        if (e.key === 'Enter') applyMemberToneDirectInput(idx);
                                        if (e.key === 'Escape') cancelMemberToneDirectInput();
                                      }}
                                      placeholder="직접 입력: 예: 공기 섞인 콧소리, 2000s K-indie airy tone"
                                      className="w-full rounded-lg border border-[#3a3a3a] bg-[#1f1f1f] px-2.5 py-2 text-[12px] font-bold text-[var(--text-primary)] placeholder:text-[var(--text-tertiary)] outline-none focus:border-brand-orange/60"
                                      autoFocus
                                    />
                                    <div className="grid grid-cols-2 gap-1.5">
                                      <button
                                        type="button"
                                        onClick={cancelMemberToneDirectInput}
                                        className="px-2.5 py-1.5 rounded-lg text-[12px] font-bold border bg-[#1f1f1f] border-[#3a3a3a] text-[var(--text-secondary)] hover:bg-[#2a2a2a]"
                                      >
                                        취소
                                      </button>
                                      <button
                                        type="button"
                                        onClick={() => applyMemberToneDirectInput(idx)}
                                        className="px-2.5 py-1.5 rounded-lg text-[12px] font-bold border bg-brand-orange border-brand-orange text-white shadow-lg shadow-[#FFB400]/20 disabled:opacity-50"
                                        disabled={!memberToneDirectDraft.trim()}
                                      >
                                        적용
                                      </button>
                                    </div>
                                  </div>
                                ) : (
                                  <button
                                    type="button"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      startMemberToneDirectInput(member);
                                    }}
                                    className="w-full flex items-center justify-between gap-3 px-2.5 py-1.5 rounded-lg text-[12px] font-bold border transition-all text-left bg-[#1f1f1f] border-[#3a3a3a] text-[var(--text-secondary)] hover:bg-[#2a2a2a] hover:text-[#FFD36A]"
                                  >
                                    <span>직접 입력</span>
                                    <Edit2 className="w-3.5 h-3.5 shrink-0" />
                                  </button>
                                )}

                                {vocalTones
                                  .filter(t => t.genderTarget === 'any' || t.genderTarget === 'unisex' || t.genderTarget === member.gender || (vocalMode === 'group' && t.genderTarget === 'group'))
                                  .map(tone => {
                                    const isToneActive = member.toneId === tone.id;
                                    return (
                                      <button
                                        key={tone.id}
                                        type="button"
                                        onClick={() => { handleUpdateMember(idx, { toneId: tone.id }); setMemberToneDirectInputId(null); setMemberToneDirectDraft(''); setActiveVocalTonePopup(null); }}
                                        className={cn(
                                          "w-full flex items-center justify-between gap-2 px-2.5 py-1.5 rounded-lg text-[12px] font-bold transition-all border text-left",
                                          isToneActive
                                            ? "bg-[#FFB400] text-[#171717] font-black border-black/20 shadow-lg shadow-[#FFB400]/20"
                                            : "bg-[#1f1f1f] border-[#3a3a3a] text-[var(--text-secondary)] hover:bg-[#2a2a2a] hover:text-[#FFD36A]"
                                        )}
                                      >
                                        <span className="leading-snug">{tone.labelKo || tone.label}</span>
                                        {isToneActive && <Check className="w-3.5 h-3.5 shrink-0" />}
                                      </button>
                                    );
                                  })}
                              </div>
                            </motion.div>
                          </Portal>
                        )}
                      </AnimatePresence>
                  </div>
                </div>
                  );
                })}
            </div>
          </div>
        )}

      </div>
    </motion.div>
      </div>

      <AnimatePresence>
        {editingVocalMember && (
          <Portal>
            <motion.div
              className="fixed inset-0 z-[10000] flex items-center justify-center bg-black/40 px-4 py-6 backdrop-blur-[1px] md:backdrop-blur-sm overscroll-none"
              initial={{ opacity: 1 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 1 }}
              transition={{ duration: 0 }}
              onPointerDown={(e) => {
                vocalCharacterBackdropPointerDownRef.current = e.target === e.currentTarget;
              }}
              onPointerUp={(e) => {
                if (vocalCharacterBackdropPointerDownRef.current && e.target === e.currentTarget) {
                  vocalCharacterBackdropPointerDownRef.current = false;
                  applyVocalCharacterAndClose();
                  return;
                }
                vocalCharacterBackdropPointerDownRef.current = false;
              }}
              onPointerCancel={() => { vocalCharacterBackdropPointerDownRef.current = false; }}
            >
              <motion.div
                initial={{ opacity: 1, scale: 1, y: 0 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 1, scale: 1, y: 0 }}
                transition={{ duration: 0 }}
                onPointerDown={(e) => e.stopPropagation()}
                onPointerUp={(e) => e.stopPropagation()}
                onClick={(e) => e.stopPropagation()}
                onWheel={blockVocalCharacterOuterScroll}
                onTouchMove={blockVocalCharacterOuterScroll}
                className="soridraw-studio-vocal-modal-panel relative flex max-h-[88vh] w-full max-w-4xl flex-col overflow-hidden rounded-3xl bg-[#111] shadow-[0_24px_70px_rgba(0,0,0,0.66)]"
              >
                <div className="flex items-center justify-between gap-3 bg-[#151515] px-5 py-4 shadow-[inset_0_-1px_0_rgba(127,189,117,0.08)]">
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <span className={cn(
                        "h-2.5 w-2.5 rounded-full",
                        editingVocalMember.gender === 'male' ? "bg-blue-400" : editingVocalMember.gender === 'female' ? "bg-pink-400" : "bg-[#FFB400]"
                      )} />
                      <h4 className="text-lg font-black text-[var(--text-primary)]">
                        {editingVocalMember.gender === 'male' ? '남성' : editingVocalMember.gender === 'female' ? '여성' : '보컬'} {editingVocalMemberIndex + 1} 캐릭터
                      </h4>
                    </div>
                    <p className="mt-1 truncate text-xs font-bold text-[#FFD36A]">{getVocalCharacterSummary({ ...editingVocalMember, character: localVocalCharacterDraft })}</p>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    {hasVocalCharacterSelection && (
                      <button
                        type="button"
                        onClick={clearLocalVocalCharacter}
                        className="soridraw-modal-reset-button"
                        title="초기화"
                      >
                        초기화
                      </button>
                    )}
                    {hasVocalCharacterChanges && (
                      <button
                        type="button"
                        onClick={applyVocalCharacterAndClose}
                        className="w-10 h-10 rounded-xl border flex items-center justify-center transition-all shrink-0 bg-[#FFB400] text-[#171717] font-black border-black/20 shadow-[0_10px_24px_rgba(0,0,0,0.16)] hover:bg-[#D49A18]"
                        title="변경 적용"
                        aria-label="변경 적용"
                      >
                        <Check className="h-4 w-4" />
                      </button>
                    )}
                    <button
                      type="button"
                      onClick={closeVocalCharacterEditor}
                      className="rounded-full bg-btn-bg p-2 text-[var(--text-secondary)] transition-all hover:bg-[#FFB400]/10 hover:text-[#FFD36A]"
                      title={hasVocalCharacterChanges ? "변경 적용 없이 닫기" : "닫기"}
                      aria-label={hasVocalCharacterChanges ? "변경 적용 없이 닫기" : "닫기"}
                    >
                      <X className="h-5 w-5" />
                    </button>
                  </div>
                </div>

                <div
                  className="custom-scrollbar flex-1 overflow-y-auto overscroll-contain px-5 py-4"
                  style={{ overscrollBehavior: 'contain' }}
                  onWheel={handleVocalCharacterWheel}
                  onTouchStart={handleVocalCharacterTouchStart}
                  onTouchMove={handleVocalCharacterTouchMove}
                >
                  <div className="space-y-5">
                    <section className="space-y-4">
                      <div className="flex items-end justify-between gap-3">
                        <div>
                          <h5 className="text-base font-black text-[var(--text-primary)]">보컬 캐릭터 게이지</h5>
                          <p className="text-xs leading-relaxed text-[var(--text-secondary)]">가운데가 기본값입니다. 움직인 항목만 보컬 프롬프트에 반영됩니다.</p>
                        </div>
                      </div>

                      <div className="space-y-3">
                        {VOCAL_CHARACTER_SCALE_CONFIGS.map((config) => {
                          const value = getVocalCharacterScaleLevel(localVocalCharacterDraft, config);
                          const step = config.steps[value - 1];
                          const isOrnament = isVocalCharacterOrnamentConfig(config);
                          const secondaryValue = isOrnament ? getVocalCharacterOrnamentSecondaryLevel(localVocalCharacterDraft, config) : config.defaultValue;
                          const secondaryStep = config.steps[secondaryValue - 1];
                          const isDefault = isVocalCharacterScaleDefaultLevel(config, value);
                          const isSecondaryDefault = !isOrnament || isVocalCharacterScaleDefaultLevel(config, secondaryValue);
                          const isCardActive = !isDefault || !isSecondaryDefault;
                          const mainPercent = config.steps.length > 1 ? ((value - 1) / (config.steps.length - 1)) * 100 : 50;
                          const secondaryPercent = config.steps.length > 1 ? ((secondaryValue - 1) / (config.steps.length - 1)) * 100 : 50;
                          const mainHandleClass = editingVocalMember?.gender === 'female'
                            ? 'vocal-character-dual-handle-female'
                            : editingVocalMember?.gender === 'male'
                              ? 'vocal-character-dual-handle-male'
                              : 'vocal-character-dual-handle-neutral';
                          return (
                            <div
                              key={config.key}
                              className={cn(
                                "rounded-2xl p-4 transition-all shadow-[0_10px_26px_rgba(0,0,0,0.18)]",
                                isCardActive
                                  ? "bg-[#FFB400]/12"
                                  : "bg-[#1a1a1a]"
                              )}
                            >
                              <div className="mb-3 flex items-start justify-between gap-3">
                                <div className="min-w-0">
                                  <div className="flex flex-wrap items-center gap-2.5">
                                    <h6 className="text-base font-black text-[#FFD36A]">{config.titleKo}</h6>
                                    <span className={cn("rounded-full px-2.5 py-0.5 text-[11px] font-black", isDefault ? "bg-btn-bg text-[var(--text-secondary)]" : "bg-[#FFB400]/14 text-[#FFD36A]")}>{step.labelKo}</span>
                                    {isOrnament && !isSecondaryDefault && (
                                      <span className="rounded-full bg-[#FFB400]/14 px-2.5 py-0.5 text-[11px] font-black text-[#FFD36A]">{secondaryStep.labelKo}</span>
                                    )}
                                  </div>
                                  <p className="mt-1.5 text-xs leading-snug text-[var(--text-secondary)]">{config.subtitleKo}</p>
                                </div>
                                <span className="shrink-0 text-xs font-black text-[#FFD36A]">{isOrnament ? `${value}/${config.steps.length}${!isSecondaryDefault ? ` · ${secondaryValue}/${config.steps.length}` : ''}` : `${value}/${config.steps.length}`}</span>
                              </div>

                              {isOrnament ? (
                                <div className="relative px-[1px] py-3">
                                  <div
                                    data-vocal-character-dual-track
                                    className="vocal-character-dual-track"
                                  >
                                    <div className="vocal-character-slider-center-marker" />
                                    <button
                                      type="button"
                                      aria-label={`${config.titleKo} 보조 기교`}
                                      title={isSecondaryDefault ? '보조기교: Gemini 자동 보정' : `보조기교: ${secondaryStep.labelKo}`}
                                      onPointerDown={(event) => handleVocalCharacterDualSliderDragStart(event, config, 'ornamentSecondaryLevel')}
                                      className="vocal-character-dual-handle vocal-character-dual-handle-secondary"
                                      style={{ left: `${secondaryPercent}%` }}
                                    />
                                    <button
                                      type="button"
                                      aria-label={`${config.titleKo} 메인 기교`}
                                      title={`메인기교: ${step.labelKo}`}
                                      onPointerDown={(event) => handleVocalCharacterDualSliderDragStart(event, config, 'ornamentLevel')}
                                      className={cn("vocal-character-dual-handle vocal-character-dual-handle-main", mainHandleClass)}
                                      style={{ left: `${mainPercent}%` }}
                                    />
                                  </div>
                                </div>
                              ) : (
                                <div className="relative px-[1px] py-2">
                                  <div className="vocal-character-slider-center-marker" />
                                  <input
                                    type="range"
                                    min={1}
                                    max={config.steps.length}
                                    step={1}
                                    value={value}
                                    onChange={(event) => updateLocalVocalCharacter({ [config.key]: Number(event.currentTarget.value) } as Partial<NonNullable<VocalMember['character']>>)}
                                    className={cn(
                                      "vocal-character-slider w-full",
                                      editingVocalMember?.gender === 'female'
                                        ? 'vocal-character-slider-female'
                                        : editingVocalMember?.gender === 'male'
                                          ? 'vocal-character-slider-male'
                                          : 'vocal-character-slider-neutral'
                                    )}
                                    aria-label={config.titleKo}
                                  />
                                </div>
                              )}

                              <div className="mt-3 flex items-center justify-between gap-2 text-[11px] font-bold text-[var(--text-secondary)]">
                                <span>{config.minLabelKo}</span>
                                <span className="truncate text-center text-[var(--text-secondary)]">{isOrnament && !isSecondaryDefault ? `${step.hintKo} + ${secondaryStep.hintKo}` : step.hintKo}</span>
                                <span>{config.maxLabelKo}</span>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </section>
                  </div>
                </div>

              </motion.div>
            </motion.div>
          </Portal>
        )}
      </AnimatePresence>
    </div>
  );
}


const VocalControl = React.memo(VocalControlComponent, (prev, next) => {
  return prev.maleCount === next.maleCount &&
         prev.femaleCount === next.femaleCount &&
         prev.vocalMode === next.vocalMode &&
         prev.rapEnabled === next.rapEnabled &&
         prev.rapMode === next.rapMode &&
         prev.isKoreanEnglishMix === next.isKoreanEnglishMix &&
         prev.englishMixRatio === next.englishMixRatio &&
         prev.isLocked === next.isLocked &&
         isArrayEqual(prev.vocalMembers, next.vocalMembers) &&
         isArrayEqual(prev.vocalTones, next.vocalTones) &&
         prev.randomActivationKey === next.randomActivationKey &&
         isArrayEqual(prev.genreHints || [], next.genreHints || []);
});

interface TempoControlProps {
  enabled: boolean;
  onEnabledChange: (val: boolean) => void;
  min: number;
  max: number;
  onMinChange: (val: number) => void;
  onMaxChange: (val: number) => void;
  onClear: () => void;
  onHover: (item: CategoryItem | null) => void;
  onLongPressStart: (item: CategoryItem) => void;
  onLongPressEnd: () => void;
}

function TempoControlComponent({ enabled, onEnabledChange, min, max, onMinChange, onMaxChange, onClear, onHover, onLongPressStart, onLongPressEnd }: TempoControlProps) {
  const sliderRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState<'min' | 'max' | null>(null);
  const [showTitleTooltip, setShowTitleTooltip] = useState(false);

  const handleStart = (type: 'min' | 'max') => {
    if (enabled) return; // If random is enabled, slider is disabled
    setIsDragging(type);
    document.body.style.userSelect = 'none';
  };

  useEffect(() => {
    const handleMove = (clientX: number) => {
      if (!isDragging || !sliderRef.current) return;

      const rect = sliderRef.current.getBoundingClientRect();
      const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
      const percent = x / rect.width;
      const val = Math.round(TEMPO_MIN_BPM + percent * (TEMPO_MAX_BPM - TEMPO_MIN_BPM));

      if (isDragging === 'min') {
        if (val <= max) onMinChange(val);
      } else {
        if (val >= min) onMaxChange(val);
      }
    };

    const onMouseMove = (e: MouseEvent) => handleMove(e.clientX);
    const onTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        handleMove(e.touches[0].clientX);
      }
    };

    const handleEnd = () => {
      setIsDragging(null);
      document.body.style.userSelect = '';
    };

    if (isDragging) {
      window.addEventListener('mousemove', onMouseMove);
      window.addEventListener('mouseup', handleEnd);
      window.addEventListener('touchmove', onTouchMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
    }

    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [isDragging, min, max, onMinChange, onMaxChange]);

  const displayMin = min;
  const displayMax = max;
  const minPos = ((displayMin - TEMPO_MIN_BPM) / (TEMPO_MAX_BPM - TEMPO_MIN_BPM)) * 100;
  const maxPos = ((displayMax - TEMPO_MIN_BPM) / (TEMPO_MAX_BPM - TEMPO_MIN_BPM)) * 100;
  const isValid = (max - min <= TEMPO_MAX_ACTIVE_RANGE) && (min !== TEMPO_MIN_BPM || max !== TEMPO_MAX_BPM);

  return (
    <div className={cn(
      "soridraw-expand-card soridraw-studio-menu-card soridraw-studio-shadow-surface bg-[var(--card-bg)] rounded-3xl px-6 py-4 border border-[var(--home-card-border)] transition-all"
    )}>
      <div className="soridraw-tempo-card-header flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
        <div className="flex items-center justify-between md:justify-start gap-3 w-full md:w-auto">
          <div className="flex items-center gap-3">
            <h3 
              onMouseEnter={() => setShowTitleTooltip(true)}
              onMouseLeave={() => setShowTitleTooltip(false)}
              className="text-[22px] font-bold text-[var(--text-primary)] flex items-center gap-2.5 cursor-help"
            >
              <span className="w-1.5 h-6 bg-[#FFB400] rounded-full" />
              템포(BPM)
            </h3>

            <div 
              className={cn(
                "soridraw-tempo-desktop-input hidden md:flex items-center gap-1 px-2.5 py-2 bg-btn-bg rounded-xl border border-btn-border shadow-btn transition-opacity",
                enabled && "opacity-30 pointer-events-none"
              )}
              onMouseEnter={() => onHover({ id: 'bpm-input-pc', label: 'BPM Input', labelKo: 'BPM 입력', description: '원하는 BPM 범위를 직접 입력합니다.' })}
              onMouseLeave={() => onHover(null)}
            >
              <input
                type="number"
                min={TEMPO_MIN_BPM}
                max={max}
                value={min}
                disabled={enabled}
                onChange={(e) => {
                  const val = parseInt(e.target.value);
                  if (!isNaN(val)) {
                    const clamped = Math.max(TEMPO_MIN_BPM, Math.min(val, max));
                    onMinChange(clamped);
                  }
                }}
                className="w-7 bg-transparent text-[#FFD36A] font-mono font-bold text-[14px] focus:outline-none text-center [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
              />
              <span className="text-[var(--text-secondary)]/50 font-bold text-sm">-</span>
              <input
                type="number"
                min={min}
                max={TEMPO_MAX_BPM}
                value={max}
                disabled={enabled}
                onChange={(e) => {
                  const val = parseInt(e.target.value);
                  if (!isNaN(val)) {
                    const clamped = Math.max(min, Math.min(val, TEMPO_MAX_BPM));
                    onMaxChange(clamped);
                  }
                }}
                className="w-7 bg-transparent text-[#FFE3A0] font-mono font-bold text-[14px] focus:outline-none text-center [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
              />
              <span className="text-[var(--text-secondary)] text-[9px] uppercase font-bold tracking-tighter">bpm</span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="soridraw-tempo-mobile-actions md:hidden flex items-center gap-2">
              <button
                data-soridraw-selected={enabled ? 'true' : 'false'}
                aria-pressed={enabled}
                onClick={() => {
                  onEnabledChange(!enabled);
                  onHover({ id: 'tempo-random-mobile', label: 'Random Tempo', labelKo: '랜덤 템포', description: '장르와 분위기에 맞는 최적의 템포로 적용됩니다.' });
                }}
                onMouseEnter={() => onHover({ id: 'tempo-random-mobile', label: 'Random Tempo', labelKo: '랜덤 템포', description: '장르와 분위기에 맞는 최적의 템포로 적용됩니다.' })}
                onMouseLeave={() => onHover(null)}
                className={cn(
                  "soridraw-tempo-random-button soridraw-tempo-random-mobile px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center gap-2",
                  enabled 
                    ? "bg-[#FFB400] text-[#171717] font-black" 
                    : "bg-white/10 text-[var(--text-primary)] hover:bg-white/20"
                )}
              >
                <Dices className={cn("w-4 h-4", enabled && "animate-pulse")} />
                <span>랜덤</span>
              </button>
              <button
                onClick={onClear}
                onMouseEnter={() => onHover({ id: 'tempo-clear-mobile', label: 'Reset', labelKo: '초기화', description: '템포 설정을 초기화합니다.' })}
                onMouseLeave={() => onHover(null)}
                className={cn(
                  "p-2.5 rounded-xl transition-all border shadow-btn",
                  (!enabled || min !== 90 || max !== 110)
                    ? "bg-[#FFB400]/20 text-[#FFD36A] border-black/20 hover:bg-[#FFB400]/30" 
                    : "bg-btn-bg text-[var(--text-secondary)] border-btn-border hover:bg-btn-hover"
                )}
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="soridraw-tempo-desktop-actions hidden md:flex items-center gap-2">
            <button
              data-soridraw-selected={enabled ? 'true' : 'false'}
              aria-pressed={enabled}
              onClick={() => {
                onEnabledChange(!enabled);
                onHover({ id: 'tempo-random-pc', label: 'Random Tempo', labelKo: '랜덤 템포', description: '장르와 분위기에 맞는 최적의 템포로 적용됩니다.' });
              }}
              onMouseEnter={() => onHover({ id: 'tempo-random-pc', label: 'Random Tempo', labelKo: '랜덤 템포', description: '장르와 분위기에 맞는 최적의 템포로 적용됩니다.' })}
              onMouseLeave={() => onHover(null)}
              className={cn(
                "soridraw-tempo-random-button soridraw-tempo-random-desktop px-6 py-3 rounded-xl text-base font-bold transition-all flex items-center gap-2",
                enabled 
                  ? "bg-[#FFB400] text-[#171717] font-black" 
                  : "bg-white/10 text-[var(--text-primary)] hover:bg-white/20"
              )}
            >
              <Dices className={cn("w-5 h-5", enabled && "animate-pulse")} />
              <span>랜덤</span>
            </button>
            <button
              onClick={onClear}
              onMouseEnter={() => onHover({ id: 'tempo-clear-pc', label: 'Reset', labelKo: '초기화', description: '템포 설정을 초기화합니다.' })}
              onMouseLeave={() => onHover(null)}
              className={cn(
                "p-2.5 rounded-xl transition-all border shadow-btn",
                (!enabled || min !== 90 || max !== 110)
                  ? "bg-[#FFB400]/20 text-[#FFD36A] border-black/20 hover:bg-[#FFB400]/30" 
                  : "bg-btn-bg text-[var(--text-secondary)] border-btn-border hover:bg-btn-hover"
              )}
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        </div>

        <div 
          className={cn(
            "soridraw-tempo-mobile-input md:hidden flex items-center justify-center gap-1 px-3 py-2 bg-white/5 rounded-xl border border-white/10 shadow-[var(--shadow-md)] transition-opacity w-fit mx-auto",
            enabled && "opacity-30 pointer-events-none"
          )}
          onMouseEnter={() => onHover({ id: 'bpm-input-mobile', label: 'BPM Input', labelKo: 'BPM 입력', description: '원하는 BPM 범위를 직접 입력합니다.' })}
          onMouseLeave={() => onHover(null)}
        >
          <input
            type="number"
            min={TEMPO_MIN_BPM}
            max={max}
            value={min}
            disabled={enabled}
            onChange={(e) => {
              const val = parseInt(e.target.value);
              if (!isNaN(val)) {
                const clamped = Math.max(TEMPO_MIN_BPM, Math.min(val, max));
                onMinChange(clamped);
              }
            }}
            className="w-9 bg-transparent text-[#FFD36A] font-mono font-bold text-base focus:outline-none text-center [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
          />
          <span className="text-[var(--text-secondary)]/50 font-bold text-base">-</span>
          <input
            type="number"
            min={min}
            max={TEMPO_MAX_BPM}
            value={max}
            disabled={enabled}
            onChange={(e) => {
              const val = parseInt(e.target.value);
              if (!isNaN(val)) {
                const clamped = Math.max(min, Math.min(val, TEMPO_MAX_BPM));
                onMaxChange(clamped);
              }
            }}
            className="w-9 bg-transparent text-[#FFE3A0] font-mono font-bold text-base focus:outline-none text-center [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
          />
          <span className="text-[var(--text-secondary)] text-[9px] uppercase font-bold tracking-tighter">bpm</span>
        </div>
      </div>

      <div 
        className={cn(
          "px-0 py-2 transition-opacity",
          enabled && "opacity-50 pointer-events-none"
        )}
        onMouseEnter={() => onHover({ id: 'bpm-slider', label: 'BPM 조절', description: '슬라이더를 드래그하여 BPM을 조절합니다.' })}
        onMouseLeave={() => onHover(null)}
      >
        <div 
          ref={sliderRef}
          className="relative h-2 bg-[var(--hover-bg)] rounded-full cursor-pointer mx-0"
          onClick={(e) => {
            if (enabled) return;
            const rect = sliderRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const percent = x / rect.width;
            const val = Math.round(TEMPO_MIN_BPM + percent * (TEMPO_MAX_BPM - TEMPO_MIN_BPM));
            
            // Snap to nearest handle but respect constraints
            if (Math.abs(val - min) < Math.abs(val - max)) {
              onMinChange(Math.min(val, max));
            } else {
              onMaxChange(Math.max(val, min));
            }
          }}
        >
          {/* Active Range Bar */}
          <div 
            className={cn(
              "absolute h-full rounded-full transition-colors",
              !enabled ? (isValid ? "bg-[#FFB400]" : "bg-[var(--text-secondary)]/30") : "bg-[#FFB400]/40"
            )}
            style={{ left: `${minPos}%`, width: `${maxPos - minPos}%` }}
          />

          {/* Min Handle */}
          <div 
            onMouseDown={(e) => { e.stopPropagation(); handleStart('min'); }}
            onTouchStart={(e) => { e.stopPropagation(); handleStart('min'); }}
            className={cn(
              "absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-5 h-5 rounded-full border-2 transition-all flex items-center justify-center cursor-grab active:cursor-grabbing touch-none z-20",
              !enabled 
                ? "bg-[var(--card-bg)] border-black/20 shadow-lg shadow-[#FFB400]/20 scale-110" 
                : "bg-[var(--card-bg)] border-black/20 shadow-lg shadow-[#FFB400]/10 scale-100 cursor-not-allowed",
              isDragging === 'min' && "scale-125 border-[#B8CB93]"
            )}
            style={{ left: `${minPos}%` }}
          >
            <div className={cn("w-1.5 h-1.5 rounded-full", !enabled ? "bg-[#FFB400]" : "bg-[#FFB400]/50")} />
          </div>

          {/* Max Handle */}
          <div 
            onMouseDown={(e) => { e.stopPropagation(); handleStart('max'); }}
            onTouchStart={(e) => { e.stopPropagation(); handleStart('max'); }}
            className={cn(
              "absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-5 h-5 rounded-full border-2 transition-all flex items-center justify-center cursor-grab active:cursor-grabbing touch-none z-20",
              !enabled 
                ? "bg-[var(--card-bg)] border-[#8AA35A] shadow-lg shadow-[#8AA35A]/20 scale-110" 
                : "bg-[var(--card-bg)] border-[#8AA35A]/40 shadow-lg shadow-[#8AA35A]/10 scale-100 cursor-not-allowed",
              isDragging === 'max' && "scale-125 border-[#FFE3A0]"
            )}
            style={{ left: `${maxPos}%` }}
          >
            <div className={cn("w-1.5 h-1.5 rounded-full", !enabled ? "bg-[#8AA35A]" : "bg-[#8AA35A]/50")} />
          </div>
        </div>
        
        <div className="flex justify-between mt-3 text-[9px] font-bold text-[var(--text-secondary)] uppercase tracking-widest">
          <span>20 BPM</span>
          <span>100 BPM</span>
          <span>200 BPM</span>
        </div>
      </div>

      {/* Status Guidance Text - Repositioned to Bottom Center */}
      <div className="flex justify-center mt-2">
        {enabled ? (
          <span className="text-[#FFD36A] text-[10px] font-bold uppercase tracking-wider flex items-center gap-1.5 bg-[#FFB400]/10 px-3 py-0.5 rounded-full border border-black/20/20">
            <Sparkles className="w-3 h-3 animate-pulse" /> 랜덤 템포 적용됨
          </span>
        ) : (
          isValid ? (
            <span className="text-[#FFE3A0] text-[10px] font-bold uppercase tracking-wider flex items-center gap-1.5 bg-[#FFB400]/12 px-3 py-0.5 rounded-full border border-black/20/24">
              <Check className="w-3 h-3" /> 템포 지정됨
            </span>
          ) : (
            <span className="text-[var(--text-secondary)] text-[10px] font-bold uppercase tracking-wider bg-[var(--hover-bg)]/50 px-3 py-0.5 rounded-full border border-[var(--border-color)]">
              범위 20 이하일 때 적용
            </span>
          )
        )}
      </div>
    </div>
  );
}

const TempoControl = React.memo(TempoControlComponent, (prev, next) => {
  return prev.enabled === next.enabled &&
         prev.min === next.min &&
         prev.max === next.max;
});
